from __future__ import annotations

# common, scientific, group, tier, strata, habitat, dimorphic, sexes, also_called, also_scientific
Row = tuple


def row(
    common: str,
    scientific: str,
    group: str,
    tier: str,
    strata: list[str],
    habitat: str,
    dimorphic: bool = False,
    sexes: str | None = None,
    also_called: list[str] | None = None,
    also_scientific: list[str] | None = None,
) -> dict:
    if sexes is None:
        sexes = (
            "Males and females look different."
            if dimorphic
            else "Males and females look alike."
        )
    return {
        "common": common,
        "scientific": scientific,
        "group": group,
        "tier": tier,
        "strata": strata,
        "habitat": habitat,
        "dimorphic": dimorphic,
        "sexes": sexes,
        "also_called": also_called or [],
        "also_scientific": also_scientific or [],
    }


T1 = "Tier 1 · Near-certain"
